export interface E1Earthquake {
  comcat: string;
  time: string;
  place: string;
  magnitude: number;
  magnitudeType: string;
  depthKm: number;
  latitude: number;
  longitude: number;
  faultType: FaultType;
  maxMmi: number;
  areaKm2: Readonly<Record<7 | 8 | 9, number>>;
  /** Stations the published map was drawn with — rule 332(b)'s second clause. */
  stations: number;
}

export const E1_EARTHQUAKES: readonly E1Earthquake[] = LINES.map((l) => ({
  comcat: l[0],
  time: l[1],
  place: l[2],
  magnitude: l[3],
  magnitudeType: l[4],
  depthKm: l[5],
  latitude: l[6],
  longitude: l[7],
  faultType: l[8],
  maxMmi: l[9],
  areaKm2: { 7: l[10], 8: l[11], 9: l[12] },
  stations: l[13],
}));
